234	// 原提交内容本身被改坏（无法解析，或批次编号为空、份数不是正整数等不符合
235	// 创建要求的内容）时，不可能对应一次成功的创建：Open 必须返回
236	// ErrCorruptData，错误信息指出问题请求编号。
237	func TestOpenRejectsCorruptCreateRequestPayload(t *testing.T) {
238		cases := []struct {
239			name    string
240			payload string
241		}{
242			{"提交内容无法解析", `not-json`},
243			{"提交内容批次编号为空", `{"BatchNo":"","RecipeNo":"R1","Version":"v1","Portions":8}`},
244			{"提交内容份数为零", `{"BatchNo":"B1","RecipeNo":"R1","Version":"v1","Portions":0}`},
245			{"提交内容份数为负", `{"BatchNo":"B1","RecipeNo":"R1","Version":"v1","Portions":-2}`},
246		}
247		for _, tc := range cases {
248			t.Run(tc.name, func(t *testing.T) {
249				dir := t.TempDir()
250				good := setupCreateRequestLedger(t, dir)
251				var st persistedState
252				if err := json.Unmarshal(good, &st); err != nil {
253					t.Fatal(err)
254				}
255				st.Requests["create-b1"].Payload = tc.payload
256				bad, err := json.MarshalIndent(&st, "", "  ")
257				if err != nil {
258					t.Fatal(err)
259				}
260				if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
261					t.Fatal(err)
262				}
263	
264				s, err := Open(dir)
265				if !errors.Is(err, ErrCorruptData) {
266					t.Fatalf("提交内容损坏应返回 ErrCorruptData，得到 %v", err)
267				}
268				if s != nil {
269					s.Close()
270					t.Fatalf("损坏台账不应返回可用的 Store 对象")
271				}
272				if !strings.Contains(err.Error(), "create-b1") {
273					t.Fatalf("错误信息应指出问题请求编号 create-b1，得到 %v", err)
274				}
275				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
276				if err != nil {
277					t.Fatal(err)
278				}
279				if !bytes.Equal(got, bad) {
280					t.Fatalf("拒绝打开不应改动台账文件")
281				}
282			})
283		}
284	}
