338	// 原提交所选的配方版本不存在时，保存的创建结果不能单独作为创建成功的依据：
339	// 同编号配方的其他版本（R1/v2）即使仍在使用，也不能顶替原选的 R1/v1。
340	func TestOpenRejectsCreateRequestResultWhenRecipeVersionMissing(t *testing.T) {
341		dir := t.TempDir()
342		good := setupCreateRequestLedger(t, dir)
343		var st persistedState
344		if err := json.Unmarshal(good, &st); err != nil {
345			t.Fatal(err)
346		}
347		// 删除 R1/v1：B1 后来已改用 R1/v2，批次绑定仍然完整。依附 R1/v1 的
348		// 配方登记请求记录一并移除，让 create-b1 的原选版本缺失成为唯一的
349		// 损坏点（B3 用 v2，不受影响）。
350		kept := st.Recipes[:0]
351		for _, r := range st.Recipes {
352			if !(r.RecipeNo == "R1" && r.Version == "v1") {
353				kept = append(kept, r)
354			}
355		}
356		st.Recipes = kept
357		delete(st.Requests, "c-recipe-v1")
358		bad, err := json.MarshalIndent(&st, "", "  ")
359		if err != nil {
360			t.Fatal(err)
361		}
362		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
363			t.Fatal(err)
364		}
365	
366		s, err := Open(dir)
367		if !errors.Is(err, ErrCorruptData) {
368			t.Fatalf("原选配方版本不存在但保留创建结果应返回 ErrCorruptData，得到 %v", err)
369		}
370		if s != nil {
371			s.Close()
372			t.Fatalf("损坏台账不应返回可用的 Store 对象")
373		}
