375		for _, want := range []string{"create-b1", "B1"} {
376			if !strings.Contains(msg, want) {
377				t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
378			}
379		}
380		got, err := os.ReadFile(filepath.Join(dir, stateFileName))
381		if err != nil {
382			t.Fatal(err)
383		}
384		if !bytes.Equal(got, bad) {
385			t.Fatalf("拒绝打开不应改动台账文件")
386		}
387	}
