406		}
407		// 删除 R1/v1 及其配方登记请求：批次 B1 当前绑定 v2 仍完整，只有 u-first
408		// 的结果采用了被删除的 v1。
409		kept := st.Recipes[:0]
410		for _, r := range st.Recipes {
411			if !(r.RecipeNo == "R1" && r.Version == "v1") {
412				kept = append(kept, r)
413			}
414		}
415		st.Recipes = kept
416		delete(st.Requests, "recipe-v1")
417		bad, err := json.MarshalIndent(&st, "", "  ")
418		if err != nil {
419			t.Fatal(err)
420		}
421		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
422			t.Fatal(err)
423		}
424	
425		s2, err := Open(dir)
426		if !errors.Is(err, ErrCorruptData) {
427			t.Fatalf("结果采用的版本缺失应返回 ErrCorruptData，得到 %v", err)
428		}
429		if s2 != nil {
430			s2.Close()
431			t.Fatalf("损坏台账不应返回可用的 Store 对象")
432		}
433		msg := err.Error()
434		for _, want := range []string{"u-first", "B1", "R1", "v1"} {
435			if !strings.Contains(msg, want) {
436				t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
437			}
438		}
439	}
440	
441	// 正常写法差异不能误判为损坏：保存结果的应投量写成 1.000、实投量写成
442	// 0.000、差额写成 -1.000，与调整成功时的数量是同一数值；合法的零实投与
443	// 负差额不是损坏。台账应正常打开，重放仍返回保存的写法。
444	func TestOpenAcceptsAdjustRequestResultFormatVariants(t *testing.T) {
445		dir := t.TempDir()
446		good := setupAdjustRequestLedger(t, dir)
447	
448		bad := corruptAdjustRequestResult(t, good, func() json.RawMessage {
449			return mutatedBatchResult(t, good, "u-first", func(v *BatchView) {
450				v.Materials[0].RequiredGrams = "1.000" // 与 1 是同一数量
451				v.Materials[0].ActualGrams = "0.000"   // 与 0 是同一数量
452				v.Materials[0].DifferenceGrams = "-1.000"
453				v.Materials[1].RequiredGrams = "4.000" // 与 4 是同一数量
454			})
455		})
456		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
457			t.Fatal(err)
458		}
459	
460		s, err := Open(dir)
461		if err != nil {
462			t.Fatalf("写法差异不应判为损坏: %v", err)
463		}
464		defer s.Close()
465	
466		replay, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8)
467		if err != nil {
468			t.Fatalf("重放调整请求应成功: %v", err)
469		}
470		if replay.Materials[0].RequiredGrams != "1.000" ||
471			replay.Materials[0].ActualGrams != "0.000" ||
472			replay.Materials[0].DifferenceGrams != "-1.000" {
473			t.Fatalf("重放应返回保存的核对项写法，得到 %+v", replay.Materials[0])
474		}
475	}
476	
477	// 批次后来再次调整、开始执行、登记投料并关闭都属于批次现状，不能混入这次
478	// 调整的结果，也不能成为拒绝一份合法旧结果的理由：台账中 B1 已经历 u-first
479	// （R1/v1、8 份）、u-final（R1/v2、3 份）、开始、两条投料并关闭，其保存的
480	// u-first 结果仍是当时的草稿内容（R1/v1、8 份、空投料、零实投），打开与
481	// 重放都必须正常；重复提交返回当次成功结果，查询继续显示当前批次，不回退
482	// 状态或改写投料。
483	func TestAdjustRequestResultStaysValidAfterLaterAdjustAndClose(t *testing.T) {
484		dir := t.TempDir()
485		good := setupAdjustRequestLedger(t, dir)
486	
487		s, err := Open(dir)
488		if err != nil {
489			t.Fatalf("已再次调整并关闭的批次不应让早先合法的草稿调整结果被判损坏: %v", err)
490		}
491		defer s.Close()
492		if string(good) == "" {
493			t.Fatal("正常台账内容不应为空")
494		}
495	
496		// 重复提交第一次成功的调整：仍返回当次成功结果（R1/v1、8 份、草稿）。
497		replay, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8)
498		if err != nil {
499			t.Fatalf("重放调整请求应成功: %v", err)
500		}
501		checkFirstAdjustView(t, replay)
502	
503		// 查询继续显示当前批次（已关闭、R1/v2、3 份、两条投料），不被历史结果回退。
504		got, err := s.GetBatch("B1")
505		if err != nil {
506			t.Fatalf("查询当前批次失败: %v", err)
507		}
508		if got.BatchNo != "B1" || got.RecipeNo != "R1" || got.RecipeVersion != "v2" ||
509			got.PlannedPortions != 3 || got.Status != StatusClosed {
510			t.Fatalf("查询应显示当前已关闭批次（R1/v2、3 份），得到 %+v", got)
511		}
512		if len(got.Feedings) != 2 {
513			t.Fatalf("当前批次应保留 2 条投料，得到 %d 条", len(got.Feedings))
514		}
515		mats := materialsMap(got)
516		checkRequirement(t, mats, "M1", "750", "100.5", "-649.5") // 250×3
517		checkRequirement(t, mats, "M4", "6", "2", "-4")           // 2×3
518	}
519	
520	// 沿用字段（配方编号与版本同时留空、份数传 0）的调整语义保持不变：沿用值
521	// 只须符合完整性与数量规则，不要求与批次当前计划相同。批次后来再次调整、
522	// 开始、投料并关闭后，早先沿用字段的合法草稿结果仍不能被误判为损坏；重放
523	// 返回当时确定的结果，查询显示当前批次。
524	func TestAdjustRequestResultWithInheritedParamsStaysValid(t *testing.T) {
525		dir := t.TempDir()
526		s, err := Open(dir)
527		if err != nil {
528			t.Fatal(err)
529		}
530		registerReplayRecipes(t, s)
531		if _, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 10); err != nil {
532			t.Fatal(err)
533		}
534		// 配方留空：沿用 R1/v1，份数改为 8。
535		if _, err := s.UpdateDraftBatch("u-keep-recipe", "B1", "", "", 8); err != nil {
536			t.Fatal(err)
537		}
538		// 份数传 0：沿用 8 份，配方改为 R1/v2。
539		if _, err := s.UpdateDraftBatch("u-keep-portions", "B1", "R1", "v2", 0); err != nil {
540			t.Fatal(err)
541		}
542		// 批次后来再改为 R1/v2、4 份，开始、投料并关闭。
543		if _, err := s.UpdateDraftBatch("u-later", "B1", "", "", 4); err != nil {
544			t.Fatal(err)
545		}
546		if _, err := s.StartBatch("start-b1", "B1"); err != nil {
547			t.Fatal(err)
548		}
549		if _, err := s.AddFeeding("f1", "B1", "M1", "100", replayFeedTime(), "张三"); err != nil {
550			t.Fatal(err)
551		}
552		if _, err := s.CloseBatch("close-b1", "B1"); err != nil {
553			t.Fatal(err)
554		}
555		if err := s.Close(); err != nil {
556			t.Fatal(err)
557		}
558	
559		s2, err := Open(dir)
560		if err != nil {
561			t.Fatalf("沿用字段的合法草稿结果在批次后续演变后不应被判损坏: %v", err)
562		}
563		defer s2.Close()
564	
565		// 重放“沿用配方”的结果：当时确定的 R1/v1、8 份，不按当前 v2 套用留空。
566		replayRecipe, err := s2.UpdateDraftBatch("u-keep-recipe", "B1", "", "", 8)
567		if err != nil {
568			t.Fatalf("重放沿用配方的请求应成功: %v", err)
569		}
570		checkFirstAdjustView(t, replayRecipe)
571	
572		// 重放“沿用份数”的结果：当时沿用的 8 份，不按当前 4 份套用传 0。
573		replayPortions, err := s2.UpdateDraftBatch("u-keep-portions", "B1", "R1", "v2", 0)
574		if err != nil {
575			t.Fatalf("重放沿用份数的请求应成功: %v", err)
576		}
577		if replayPortions.RecipeNo != "R1" || replayPortions.RecipeVersion != "v2" ||
578			replayPortions.PlannedPortions != 8 || replayPortions.Status != StatusDraft {
579			t.Fatalf("重放结果应是当时的 R1/v2、8 份、草稿，得到 %+v", replayPortions)
580		}
581		rpMats := materialsMap(replayPortions)
582		checkRequirement(t, rpMats, "M1", "2000", "0", "-2000") // 250 × 8
583		checkRequirement(t, rpMats, "M4", "16", "0", "-16")     // 2 × 8
584	
585		// 查询仍显示当前已关闭批次（R1/v2、4 份、投料保留）。
586		got, err := s2.GetBatch("B1")
587		if err != nil {
588			t.Fatal(err)
589		}
590		if got.RecipeVersion != "v2" || got.PlannedPortions != 4 || got.Status != StatusClosed {
591			t.Fatalf("查询应显示当前已关闭批次，得到 %+v", got)
592		}
593		if len(got.Feedings) != 1 || got.Feedings[0].MaterialNo != "M1" ||
594			got.Feedings[0].Grams != "100" {
595			t.Fatalf("当前批次投料应保留，得到 %+v", got.Feedings)
596		}
597	}
598	
599	// 台账正常打开后，保存内容中的调整请求结果被改坏：下一次查询或写入必须
600	// 返回 ErrCorruptData——即使本次访问的是另一条正常批次，也不能忽略损坏的
601	// 调整请求；被拒绝的重放不得返回损坏结果，被拒绝的写入不留业务变化、不
602	// 占用请求编号，原台账内容不变。恢复后原成功请求仍可幂等重放，被拒绝过的
603	// 请求编号可以正常使用。
604	func TestAdjustRequestResultCorruptionAfterOpenDetectedOnNextAccess(t *testing.T) {
605		dir := t.TempDir()
606		good := setupAdjustRequestLedger(t, dir)
607	
608		s, err := Open(dir)
609		if err != nil {
610			t.Fatal(err)
611		}
612		defer s.Close()
613	
614		// 打开后把 u-first 的保存结果改坏为空对象（其余记录保持完整）。
615		bad := corruptAdjustRequestResult(t, good, func() json.RawMessage {
616			return json.RawMessage(`{}`)
617		})
618		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
619			t.Fatal(err)
620		}
621	
622		// 查询损坏批次与正常批次都必须失败，不能沿用此前读到的内容，也不能跳过
623		// 损坏结果继续使用另一条正常记录。
624		for _, batchNo := range []string{"B1", "B3"} {
625			if v, err := s.GetBatch(batchNo); !errors.Is(err, ErrCorruptData) {
626				t.Fatalf("查询批次 %q 应返回 ErrCorruptData，得到 %v", batchNo, err)
627			} else if v != nil {
628				t.Fatalf("被拒绝的查询不应返回部分台账视图: %+v", v)
629			}
630		}
631		// 用原编号、原内容重放损坏的调整请求：不得把损坏的保存结果当成成功结果
632		// 返回，必须报损坏。
633		if _, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8); !errors.Is(err, ErrCorruptData) {
634			t.Fatalf("重放损坏的调整请求应返回 ErrCorruptData，得到 %v", err)
635		}
636		// 对正常批次的新写入同样不能绕过损坏结果。
637		if _, err := s.StartBatch("start-b3", "B3"); !errors.Is(err, ErrCorruptData) {
638			t.Fatalf("损坏台账上开始正常批次应返回 ErrCorruptData，得到 %v", err)
639		}
640	
641		// 被拒绝的访问不改动文件、不占用请求编号、不留下业务变更。
642		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
643		if err != nil {
644			t.Fatal(err)
645		}
646		if !bytes.Equal(after, bad) {
647			t.Fatalf("被拒绝的访问不应改动台账文件")
648		}
649		if bytes.Contains(after, []byte("start-b3")) {
650			t.Fatalf("被拒绝的写入不应留下请求记录")
651		}
652	
653		// 恢复后：原成功请求仍取回当次调整结果，被拒绝过的请求编号可以正常使用。
654		if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
655			t.Fatal(err)
656		}
657		replay, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8)
658		if err != nil {
659			t.Fatalf("恢复后重放原成功请求失败: %v", err)
660		}
661		checkFirstAdjustView(t, replay)
662		started, err := s.StartBatch("start-b3", "B3")
663		if err != nil {
664			t.Fatalf("被拒绝过的请求编号应仍可合法提交: %v", err)
665		}
666		if started.Status != StatusExecuting || started.BatchNo != "B3" {
667			t.Fatalf("B3 应被正常开始执行，得到 %+v", started)
668		}
669	}
670	
671	// 任何一条成功调整请求损坏都应拒绝整份台账：改坏 u-b2 的结果后，即使调用方
672	// 只查询/操作正常的 B1、B3，Open 也必须返回 ErrCorruptData。
673	func TestAnyCorruptAdjustRequestRejectsWholeLedger(t *testing.T) {
674		dir := t.TempDir()
675		good := setupAdjustRequestLedger(t, dir)
676		bad := corruptRequestResult(t, good, "u-b2", func() json.RawMessage {
677			return json.RawMessage(`{}`)
678		})
679		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
680			t.Fatal(err)
681		}
682	
683		s, err := Open(dir)
684		if !errors.Is(err, ErrCorruptData) {
685			t.Fatalf("任一调整请求损坏都应返回 ErrCorruptData，得到 %v", err)
686		}
687		if s != nil {
688			s.Close()
689			t.Fatalf("损坏台账不应返回可用的 Store 对象")
690		}
691		if !strings.Contains(err.Error(), "u-b2") {
692			t.Fatalf("错误信息应指出问题请求编号 u-b2，得到 %v", err)
693		}
694	}
695	
696	// 白盒核对：正常台账中 u-first 的保存结果确实是这次调整成功时的内容，且本
697	// 文件的改坏辅助函数确实改动了文件内容（防止测试因辅助函数失效而假性通过）。
698	func TestAdjustRequestCorruptionHelpersWork(t *testing.T) {
699		dir := t.TempDir()
700		good := setupAdjustRequestLedger(t, dir)
701	
702		var saved BatchView
703		if err := json.Unmarshal(createResultRaw(t, good, "u-first"), &saved); err != nil {
704			t.Fatal(err)
705		}
706		if saved.BatchNo != "B1" || saved.RecipeNo != "R1" || saved.RecipeVersion != "v1" ||
707			saved.RecipeName != "配方初版" || saved.PlannedPortions != 8 ||
708			saved.Status != StatusDraft || len(saved.Feedings) != 0 || len(saved.Materials) != 2 {
709			t.Fatalf("正常台账中保存的调整结果应为这次调整成功时的内容，得到 %+v", saved)
710		}
711		bad := corruptAdjustRequestResult(t, good, func() json.RawMessage {
712			return json.RawMessage(`{}`)
713		})
714		if bytes.Equal(good, bad) {
715			t.Fatal("改坏辅助函数未改动台账内容")
716		}
717		// 正常台账本身必须能打开：所有“正常后续操作不误判”的前提。
718		s, err := Open(dir)
719		if err != nil {
720			t.Fatalf("正常台账应能打开: %v", err)
721		}
722		s.Close()
723	}
