		{"close/空对象结果+批次在", func() error {
			p, _ := json.Marshal(closeBatchPayload{BatchNo: "B1"})
			req := &requestRecord{Op: opCloseBatch, Payload: string(p), Result: json.RawMessage(`{}`)}
			return validateCloseBatchRequest(probeState(), "rq", req)
		}},
		{"close/批次未关闭", func() error {
			st := probeState()
			st.Batches[0].Status = StatusExecuting
			p, _ := json.Marshal(closeBatchPayload{BatchNo: "B1"})
			req := &requestRecord{Op: opCloseBatch, Payload: string(p), Result: probeResult("B1", StatusClosed, "R1", "v1", "配方一", 5)}
			return validateCloseBatchRequest(st, "rq", req)
		}},
		{"close/结果属于另一批次", func() error {
			st := probeState()
			st.Batches[0].Status = StatusClosed
			st.Batches[1].Status = StatusClosed
			p, _ := json.Marshal(closeBatchPayload{BatchNo: "B1"})
			req := &requestRecord{Op: opCloseBatch, Payload: string(p), Result: probeResult("B2", StatusClosed, "R1", "v1", "配方一", 5)}
			return validateCloseBatchRequest(st, "rq", req)
		}},
	}
	for _, tc := range cases {
		err := tc.run()
		fmt.Printf("PROBE|%s|%v\n", tc.label, err)
	}
}
